 const fit=()=>{const sw=stage.clientWidth-20,sh=stage.clientHeight-20,w=img.naturalWidth||1,h=img.naturalHeight||1;const r=rot%180?Math.min(sw/h,sh/w):Math.min(sw/w,sh/h);z=Math.min(1,r);dx=dy=0;ap()};
 const load=p=>{const v=node(p);if(typeof v!='string'||!v.startsWith('data:image')){nm.textContent='Not an image';return}img.src=v;img.alt=p.at(-1);nm.textContent=p.at(-1)+(list.length>1?`  (${i+1}/${list.length})`:'');W.setTitle('Image Viewer - '+p.at(-1));rot=0;fl=1;img.onload=fit;recentAdd(p)};
