 q('.zi').onclick=()=>{scale*=1.2;render()};q('.zo').onclick=()=>{scale/=1.2;render()};q('.fw').onclick=async()=>{if(!doc)return;const p=await doc.getPage(page);scale=(stage.clientWidth-30)/p.getViewport({scale:1}).width;render()};
 q('.fd').onkeydown=async e=>{if(e.key!='Enter'||!doc)return;const t=e.target.value.toLowerCase();for(let k=1;k<=doc.numPages;k++){const n=((page-1+k)%doc.numPages)+1;const tc=await(await doc.getPage(n)).getTextContent();if(tc.items.map(x=>x.str).join(' ').toLowerCase().includes(t)){page=n;render();stat.textContent='Found on page '+n;return}}stat.textContent='Not found.'};
